dir:


































  &DefaultButton;




function dir$dmnhombp(p){
  this.constructor(p);
}
dir$dmnhombp.prototype = new DirEvent();
dir$dmnhombp.prototype.afterInit = function(){
  var p = this._dir;
}
dir$dmnhombp.prototype.afterInit = function(renderType){
  var p = this._dir,g = p.grid()

dir$dmnhombpDisabledMasterField(p, g);

}

function dir$dmnhombpDisabledMasterField(p, g){

  if(p.valForm('ma_nhom').trim() != '')
  {
    p.setDisabled('ma_nhom', true);
  }
  else
  {
    p.setDisabled('ma_nhom', false);
  }
}






	.control-label.ma_nhom, .control-label.ten_nhom
	{	

		color: #499b98;;
	}









declare @codeExistsNewMsg nvarchar(256), @codeExistsEditMsg nvarchar(256)
select @codeExistsNewMsg = case when '@@lan' = 'v' then N'Mã nhóm bộ phận đã tồn tại' else N'Department groups code already exists' end
select @codeExistsEditMsg = case when '@@lan' = 'v' then N'Mã nhóm bộ phận đã tồn tại' else N'Department groups code already exists' end
